#!/usr/bin/env node
/**
 * scripts/check-filter-wiring.mjs — the guard for ONE filter, three wings.
 *
 * The AFM catalog page is generated by three independent scripts that share a
 * single search box. Each used to ship its own inline filter: the box read
 * "SEARCH THE ARCHIVE", searched Wing A only, and answered "nothing matches"
 * for a word that was sitting in a Wing C row further down the same page.
 *
 * A unit test on the shared controller would not have caught that — the bug
 * was a WING THAT STOPPED USING IT. So this asserts the wiring instead:
 * exactly one filter script, and every row/chip/divider/empty-state on the
 * page speaking the contract that controller reads.
 *
 * Prove it fails: drop data-wing from a row template, or paste a second
 * <script> into any wing block, and re-run. Both go red.
 *
 * NO DEPENDENCIES on purpose — same contract as check-site.mjs.
 */
import { readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const html = readFileSync(join(ROOT, "newsletter.html"), "utf8");
const fails = [];
const ok = (label, cond, detail = "") => {
  console.log(`  ${cond ? "PASS" : "FAIL"}  ${label}${detail ? ` — ${detail}` : ""}`);
  if (!cond) fails.push(label);
};

// 1. exactly one filter controller on the page
const scripts = html.match(/<script>/g) || [];
ok("exactly one inline <script> (the shared filter controller)",
   scripts.length === 1, `found ${scripts.length}`);
ok("the controller is the shared one from afm-chrome.mjs",
   html.includes('document.querySelectorAll(".afm-row")'));

// 2. no wing kept a private filter
for (const dead of ['querySelectorAll(".catalog-row")', 'querySelectorAll(".email-row")', "data-eyear"]) {
  ok(`no leftover per-wing filter (${dead})`, !html.includes(dead));
}

// 3. every row carries the contract attributes
const rows = html.match(/<a class="[^"]*\brow\b[^"]*"[^>]*>/g) || [];
const rowsWired = rows.filter((r) => /class="[^"]*afm-row/.test(r) && /data-wing="[ABC]"/.test(r) && /data-year="\d{4}"/.test(r));
ok("every catalog/email row is wired (afm-row + data-wing + data-year)",
   rows.length > 0 && rows.length === rowsWired.length, `${rowsWired.length}/${rows.length}`);

// 4. every wing present in rows also has chips-or-none and ONE honest empty state
const wings = [...new Set(rows.map((r) => (r.match(/data-wing="([ABC])"/) || [])[1]).filter(Boolean))].sort();
ok("all three wings render rows", wings.join("") === "ABC", wings.join("") || "none");
for (const w of wings) {
  const empties = (html.match(new RegExp(`class="afm-empty" data-wing="${w}"`, "g")) || []).length;
  ok(`wing ${w} has exactly one empty state`, empties === 1, `found ${empties}`);
}

// 5. every chip names a wing, or the controller silently ignores it
const chips = html.match(/<button[^>]*class="afm-chip[^"]*"[^>]*>/g) || [];
const strays = chips.filter((c) => !/data-wing="[ABC]"/.test(c) && !/id="afm-filter-full"/.test(c));
ok("every year chip names its wing", strays.length === 0, strays.join(" "));

// 6. the search box must not promise more than it filters
const searchesAll = html.includes('id="afm-filter-q"') && html.includes('document.querySelectorAll(".afm-row")');
ok("the search box is backed by an all-wings filter", searchesAll);

console.log(`check-filter-wiring: ${fails.length ? "FAIL" : "PASS"}`);
process.exit(fails.length ? 1 : 0);
